////  CityViewModel.swift//  YP_Trains//import SwiftUIimport Combineimport OpenAPIURLSessionclass CityViewModel: ObservableObject {    @Published var searchText = ""    @Published var allCities: [CityModel] = [] // Теперь храним все загруженные города    @Published var filteredCities: [CityModel] = [] // Города для отображения на экране        let yaApiKey = Config.shared.getApiKey()        init() {        fetshAllStations(apiKey: yaApiKey)    }        func fetshAllStations(apiKey: String) {        Task {            do {                // 1. Формируем URL для прямого запроса                let urlString = "https://api.rasp.yandex.net/v3.0/stations_list/?apikey=\(apiKey)&format=json"                                guard let url = URL(string: urlString) else {                    print("Ошибка: неверный URL")                    return                }                                print("Fetching allStations via URLSession...")                                // 2. Делаем стандартный сетевой запрос                let (data, response) = try await URLSession.shared.data(from: url)                                guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {                    print("Ошибка: сервер вернул не 200")                    return                }                                // 3. Парсим JSON напрямую в нашу QuickType модель AllStationModel                let model = try JSONDecoder().decode(AllStationModel.self, from: data)                                // 4. МАППИНГ ГОРОДОВ С ФИЛЬТРОМ ПО СТРАНЕ                let allSettlements = model.countries                    .filter { $0.title == "Россия" } // <--- ДОБАВЛЕН ФИЛЬТР: БЕРЕМ ТОЛЬКО РОССИЮ                    .flatMap { country in                        country.regions.flatMap { region in                            region.settlements                        }                    }                                // 5. Преобразуем Settlement в нашу UI-модель CityModel                let cities = allSettlements.map { CityModel(from: $0) }                                // 6. Удаляем дубликаты                var uniqueCities: [CityModel] = []                var seenTitles = Set<String>()                                for city in cities {                    let uniqueKey = "\(city.title)_\(city.yandexCode ?? "nil")"                                        if !seenTitles.contains(uniqueKey) {                        seenTitles.insert(uniqueKey)                        uniqueCities.append(city)                    }                }                                // 7. Сортируем по алфавиту                let sortedCities = uniqueCities.sorted { $0.title < $1.title }                                // 8. Обновляем UI на главном потоке                await MainActor.run {                    self.allCities = sortedCities                    self.filterCities()                    print("Successfully loaded \(sortedCities.count) cities in Russia.")                }                            } catch {                print("Error fetching or decoding allStations: \(error)")            }        }    }        func filterCities() {        if searchText.isEmpty {            filteredCities = allCities        } else {            // Ищем по полю title, так как теперь мы используем CityModel с title            filteredCities = allCities.filter {                $0.title.localizedCaseInsensitiveContains(searchText)            }        }    }        func clearSearch() {        searchText = ""        filterCities()    }}